package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

// callNext invokes balancer.Next and reports whether it panicked.
func callNext(t *testing.T, b ProxyBalancer, c echo.Context) (target *ProxyTarget, panicked bool) {
	t.Helper()
	defer func() {
		if r := recover(); r != nil {
			panicked = true
			target = nil
			t.Logf("PANIC recovered: %v", r)
		}
	}()
	target = b.Next(c)
	return target, false
}

func TestVerifyTempBalancersEmpty(t *testing.T) {
	e := echo.New()
	c := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())

	// 1. random balancer with nil targets
	rb := NewRandomBalancer(nil)
	got, panicked := callNext(t, rb, c)
	if panicked {
		t.Errorf("NewRandomBalancer(nil).Next(c) panicked")
	} else if got != nil {
		t.Errorf("NewRandomBalancer(nil).Next(c) = %v, want nil", got)
	} else {
		t.Logf("PASS: NewRandomBalancer(nil).Next(c) == nil, no panic")
	}

	// 2. round robin balancer with empty (non-nil) slice
	rrb := NewRoundRobinBalancer([]*ProxyTarget{})
	got, panicked = callNext(t, rrb, c)
	if panicked {
		t.Errorf("NewRoundRobinBalancer([]*ProxyTarget{}).Next(c) panicked")
	} else if got != nil {
		t.Errorf("NewRoundRobinBalancer([]*ProxyTarget{}).Next(c) = %v, want nil", got)
	} else {
		t.Logf("PASS: NewRoundRobinBalancer([]*ProxyTarget{}).Next(c) == nil, no panic")
	}

	// 2b. round robin balancer with nil slice too (extra)
	rrbNil := NewRoundRobinBalancer(nil)
	got, panicked = callNext(t, rrbNil, c)
	if panicked {
		t.Errorf("NewRoundRobinBalancer(nil).Next(c) panicked")
	} else if got != nil {
		t.Errorf("NewRoundRobinBalancer(nil).Next(c) = %v, want nil", got)
	} else {
		t.Logf("PASS: NewRoundRobinBalancer(nil).Next(c) == nil, no panic")
	}

	// 2c. repeated calls on empty balancers must stay nil / non-panicking
	for i := 0; i < 5; i++ {
		if got, panicked = callNext(t, rb, c); panicked || got != nil {
			t.Errorf("call %d on empty random balancer: got=%v panicked=%v, want nil/false", i, got, panicked)
		}
		if got, panicked = callNext(t, rrb, c); panicked || got != nil {
			t.Errorf("call %d on empty round-robin balancer: got=%v panicked=%v, want nil/false", i, got, panicked)
		}
	}
	t.Logf("PASS: repeated Next() on empty balancers returns nil without panic")
}

func TestVerifyTempSingleTarget(t *testing.T) {
	e := echo.New()
	c := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())

	target := &ProxyTarget{Name: "only", URL: mustParseURL(t, "http://only.local")}

	rb := NewRandomBalancer([]*ProxyTarget{target})
	for i := 0; i < 5; i++ {
		got, panicked := callNext(t, rb, c)
		if panicked {
			t.Fatalf("random balancer with 1 target panicked on call %d", i)
		}
		if got != target {
			t.Fatalf("random balancer with 1 target: got %v, want %v", got, target)
		}
	}

	rrb := NewRoundRobinBalancer([]*ProxyTarget{target})
	for i := 0; i < 5; i++ {
		got, panicked := callNext(t, rrb, c)
		if panicked {
			t.Fatalf("round-robin balancer with 1 target panicked on call %d", i)
		}
		if got != target {
			t.Fatalf("round-robin balancer with 1 target: got %v, want %v", got, target)
		}
	}
	t.Logf("PASS: balancers with 1 target always return that target")
}

func TestVerifyTempRoundRobinAlternates(t *testing.T) {
	e := echo.New()
