// Bug 2: Context.Path must be empty when no route matched.
func TestZZBug2Path(t *testing.T) {
	e := New()
	captured := "unset"
	e.GET("/users/:id", func(c Context) error { return c.String(http.StatusOK, "ok") })
	e.HTTPErrorHandler = func(err error, c Context) {
		captured = c.Path()
	}

	req := httptest.NewRequest(http.MethodGet, "/does-not-exist", nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	if captured != "" {
		t.Errorf("bug2: 404 path = %q, want %q", captured, "")
	}
	if rec.Code != http.StatusNotFound {
		t.Errorf("bug2: status = %d, want 404", rec.Code)
	}

	captured = "unset"
	req = httptest.NewRequest(http.MethodGet, "/users/1", nil)
	rec = httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	if captured != "/users/:id" {
		t.Errorf("bug2: matched path = %q, want %q", captured, "/users/:id")
	}
	if rec.Code != http.StatusOK {
		t.Errorf("bug2: status = %d, want 200", rec.Code)
	}
	t.Logf("bug2 observed: 404 path=%q status=%d; matched path=%q", "", rec.Code, captured)
}

